---------------------------- MODULE MC_DistributedTransaction ----------------------------
EXTENDS DistributedTransaction

CONSTANTS k1, k2, c1, c2

MC_KEY == {k1, k2}

MC_PESSIMISTIC_CLIENT == {c1}

MC_OPTIMISTIC_CLIENT == {c2}

MC_CLIENT_READ_KEY == 
    c1 :> {} @@ c2 :> {k1, k2}

MC_CLIENT_WRITE_KEY ==
    c1 :> {k1, k2} @@ c2 :> {k1, k2}

MC_CLIENT_PRIMARY ==
    c1 :> k1 @@ c2 :> k1

=========================================================================================
